<?php

declare(strict_types=1);

namespace HangTuah\GateTrail\Database\Schema\Inspection\PostgreSql;

/**
 * How PostgreSQL generates a key column's value.
 *
 * PostgreSQL has two legitimate representations of the canonical
 * "generated key" contract, and GateTrail's two provisioning modes each
 * produce a different one:
 *
 * - {@see self::ByDefault} — `GENERATED BY DEFAULT AS IDENTITY`, emitted by
 *   the release `0001` DBA artifacts;
 * - {@see self::SequenceDefault} — a `nextval(...)` column default, which is
 *   what Laravel's `bigserial` produces for package-managed migrations.
 *
 * Both accept an explicitly supplied identifier. {@see self::Always} does not,
 * so it is drift rather than an equivalent representation.
 *
 * @internal
 */
enum PostgreSqlIdentityGeneration: string
{
    case Always = 'always';
    case ByDefault = 'by_default';
    case SequenceDefault = 'sequence_default';

    public function acceptsExplicitValue(): bool
    {
        return $this !== self::Always;
    }
}
